
.welcome-page {
  min-height: 100dvh;
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  /* [ใหม่] พื้นหลังหน้า Login เป็นภาพ Board Game ฟาร์ม (public/images/login.jpg)
     แทน gradient เดิม — background-color เดิมไว้เป็น fallback สีระหว่างรอโหลด
     ภาพ/กรณีโหลดภาพไม่สำเร็จ ไม่ให้เห็นพื้นขาวโล่ง ๆ */
  background: url('/images/login.jpg') center / cover no-repeat, var(--farm-grass);
}

.welcome-page__scroll {
  width: 100%;
  max-width: 420px;
  padding: 2rem 1.25rem;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  background: var(--farm-cream);
  border: 3px solid var(--farm-wood);
  border-radius: 1.5rem;
  box-shadow: 0 12px 0 -4px var(--farm-wood-dark), 0 20px 32px -12px rgba(74, 47, 24, 0.35);
}

.brand-mark {
  width: 4rem;
  height: 4rem;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 999px;
  background: linear-gradient(135deg, var(--farm-grass) 0%, var(--farm-accent-dark) 100%);
  margin-bottom: 1.25rem;
  box-shadow: 0 8px 24px -8px rgba(90, 158, 51, 0.6);
  border: 3px solid var(--farm-cream);
}

.brand-mark__icon {
  width: 2.1rem;
  height: 2.1rem;
  color: var(--farm-cream);
}

.title {
  font-size: 1.6rem;
  font-weight: 700;
  letter-spacing: -0.01em;
  color: var(--farm-text-dark);
  margin: 0;
}

.subtitle {
  font-size: 0.9rem;
  line-height: 1.5;
  color: var(--farm-text-muted);
  margin: 0.4rem 0 2rem;
}

.welcome-page__error {
  font-size: 0.8rem;
  color: #b3441f;
  margin: -1.25rem 0 1.25rem;
}

.welcome-page__buttons {
  margin-top: 0.25rem;
}

.fade-enter-active,
.fade-leave-active {
  transition: opacity 0.2s ease;
}

.fade-enter-from,
.fade-leave-to {
  opacity: 0;
}
